using System.Data; using Dapper; using HabitFlow.Domain; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection; using Npgsql;
namespace HabitFlow.Infrastructure;
public sealed class DbConnectionFactory(IConfiguration cfg){public IDbConnection Create()=>new NpgsqlConnection(cfg.GetConnectionString("DefaultConnection"));}
public sealed class SqlExecutor(DbConnectionFactory f){public async Task<T?> QuerySingleOrDefaultAsync<T>(string sql,object? p=null){using var c=f.Create(); return await c.QuerySingleOrDefaultAsync<T>(sql,p);} public async Task<IReadOnlyList<T>> QueryAsync<T>(string sql,object? p=null){using var c=f.Create(); var rows=await c.QueryAsync<T>(sql,p); return rows.AsList();} public async Task<int> ExecuteAsync(string sql,object? p=null){using var c=f.Create(); return await c.ExecuteAsync(sql,p);}}
public static class DependencyInjection{public static IServiceCollection AddInfrastructure(this IServiceCollection s){s.AddSingleton<DbConnectionFactory>();s.AddScoped<SqlExecutor>();s.AddScoped<IUserRepository,UserRepository>();s.AddScoped<IHabitRepository,HabitRepository>();s.AddScoped<IHabitCompletionRepository,HabitCompletionRepository>();s.AddScoped<IAuditRepository,AuditRepository>();return s;}}
public sealed class UserRepository(SqlExecutor db):IUserRepository{public Task<User?> GetByEmailAsync(string email,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<User>("select * from habitflow.users where email=@email",new{email}); public Task<User?> GetByIdAsync(Guid id,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<User>("select * from habitflow.users where id=@id",new{id}); public Task CreateAsync(User u,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.users(id,name,email,password_hash,role,account_status,plan,plan_status,wants_premium_notice,onboarding_completed,created_at,updated_at) values(@Id,@Name,@Email,@PasswordHash,@Role,@AccountStatus,@Plan,@PlanStatus,@WantsPremiumNotice,@OnboardingCompleted,@CreatedAt,@UpdatedAt)",u); public Task UpdateLastLoginAsync(Guid id,DateTime at,CancellationToken ct=default)=>db.ExecuteAsync("update habitflow.users set last_login_at=@at where id=@id",new{id,at}); public async Task<IReadOnlyList<User>> SearchAsync(string? email,CancellationToken ct=default)=>await db.QueryAsync<User>("select * from habitflow.users where @email is null or email ilike @pattern order by created_at desc limit 100",new{email,pattern=$"%{email}%"});}
public sealed class HabitRepository(SqlExecutor db):IHabitRepository{public async Task<int> CountActiveAsync(Guid userId,CancellationToken ct=default)=>await db.QuerySingleOrDefaultAsync<int>("select count(*) from habitflow.habits where user_id=@userId and is_archived=false",new{userId}); public async Task<IReadOnlyList<Habit>> ListAsync(Guid userId,bool includeArchived=false,CancellationToken ct=default)=>await db.QueryAsync<Habit>("select * from habitflow.habits where user_id=@userId and (@includeArchived or is_archived=false) order by created_at desc",new{userId,includeArchived}); public Task CreateAsync(Habit h,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.habits(id,user_id,name,color,category,is_archived,created_at,updated_at) values(@Id,@UserId,@Name,@Color,@Category,@IsArchived,@CreatedAt,@UpdatedAt)",h); public Task ArchiveAsync(Guid id,Guid userId,bool archived,CancellationToken ct=default)=>db.ExecuteAsync("update habitflow.habits set is_archived=@archived, archived_at=case when @archived then now() else null end where id=@id and user_id=@userId",new{id,userId,archived});}
public sealed class HabitCompletionRepository(SqlExecutor db):IHabitCompletionRepository{public async Task<IReadOnlyList<HabitCompletion>> ListAsync(Guid userId,DateOnly from,DateOnly to,CancellationToken ct=default)=>await db.QueryAsync<HabitCompletion>("select * from habitflow.habit_completions where user_id=@userId and completed_date between @from and @to",new{userId,from,to}); public Task CompleteAsync(HabitCompletion c,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.habit_completions(id,habit_id,user_id,completed_date,created_at) values(@Id,@HabitId,@UserId,@CompletedDate,@CreatedAt) on conflict do nothing",c); public Task UncompleteAsync(Guid habitId,Guid userId,DateOnly date,CancellationToken ct=default)=>db.ExecuteAsync("delete from habitflow.habit_completions where habit_id=@habitId and user_id=@userId and completed_date=@date",new{habitId,userId,date});}
public sealed class AuditRepository(SqlExecutor db):IAuditRepository{public Task AddSystemAsync(SystemAuditLog l,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.system_audit_logs(id,user_id,user_email,severity,source,action,message,metadata,error_code,error_fingerprint,created_at,read_by_admin) values(@Id,@UserId,@UserEmail,@Severity,@Source,@Action,@Message,@Metadata::jsonb,@ErrorCode,@ErrorFingerprint,@CreatedAt,@ReadByAdmin)",l); public Task AddAdminAsync(AdminAuditLog l,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.admin_audit_logs(id,admin_user_id,admin_email,action,target_user_id,target_user_email,reason,metadata,created_at) values(@Id,@AdminUserId,@AdminEmail,@Action,@TargetUserId,@TargetUserEmail,@Reason,@Metadata::jsonb,@CreatedAt)",l);}
